discrete VoltageControlSystem
port:
    event input real VoltageDeviation;
    event output real VoltageStable;
state:
    initial state State1
        when entry() then
            statehold(0);
        end;
        when receive(VoltageDeviation) then
            transition(State2);
        end;
    end;

    state State2
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(State3);
        end;
    end;

    state State3
        when entry() then
            statehold(0);
        end;
        when T1 then
            transition(State1);
            out
                send(VoltageStable, 1);
        end;
        when E1 then
            transition(State1);
            out
                send(VoltageStable, 1);
        end;
    end;
end;
end;

discrete CurrentControlSystem
port:
    event input real Restart;  // Start or restart
event input real ExceedsSafetyLimit;  // The current goes beyond the safety limit.
event input real ManualConfirmation;  // Manual confirmation is back to normal.
event input real HardwareFailure;  // Hardware failure
event output real FaultHandling;  // Fault management signal.
state:
    initial state State1
        when entry() then
            statehold(0);
        end;
        when receive(Restart) then
            transition(State2);
        end;
        when receive(HardwareFailure) then
            transition(State4);
        end;
    end;

    state State2
        when entry() then
            statehold(0);
        end;
        when receive(ExceedsSafetyLimit) then
            transition(State3);
        end;
        when receive(HardwareFailure) then
            transition(State4);
        end;
    end;

    state State3
        when entry() then
            statehold(0);
        end;
        when receive(ManualConfirmation) then
            transition(State2);
        end;
        when receive(HardwareFailure) then
            transition(State4);
        end;
    end;

    state State4
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(State1);
            out
                send(FaultHandling, 1);
        end;
    end;
end;
end;

discrete DataCollectionAndAnalysisSystem
port:
    event input real StartDataCollection;
    event output real DataCollected;
    event output real AnalysisComplete;
state:
    initial state State1
        when entry() then
            statehold(0);
        end;
        when receive(StartDataCollection) then
            transition(State2);
        end;
    end;

    state State2
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(State3);
            out
                send(DataCollected, 1);
        end;
    end;

    state State3
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(State4);
        end;
    end;

    state State4
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(State1);
            out
                send(AnalysisComplete, 1);
        end;
    end;
end;
end;

